function run(args){const safari=Application('Safari'),w=safari.windows[0],x=Number(args[0]),y=Number(args[1]);if(w.id()!==1296||!w.currentTab.url().startsWith('http://127.0.0.1:4185/#document='))throw Error('Wrong front window');const b=w.bounds();if(!Number.isFinite(x)||!Number.isFinite(y)||x<b.x+10||x>b.x+b.width-10||y<b.y+70||y>b.y+b.height-10)throw Error('Pointer outside owned content');safari.activate();if(safari.windows[0].id()!==1296||!safari.windows[0].currentTab.url().startsWith('http://127.0.0.1:4185/#document='))throw Error('Focus changed before click');Application('System Events').processes.byName('Safari').click({at:[x,y]});return 'Click delivered in owned VDoc content';}
